def is_perfect_cube(n):
    if n == 0:
        return True
    # Handle negative numbers
    sign = 1
    if n < 0:
        sign = -1
        n = -n

    # Estimate the cube root
    import math
    cbrt_approx = round(n**(1/3))

    # Check cbrt_approx and its neighbors
    for c in range(cbrt_approx - 2, cbrt_approx + 3):
        if c**3 == n:
            return True
    return False

print("\nPerfect Cube Check:")
for x, val in results.items():
